import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Hotkeys (Settings Page)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/hotkeys-page.md","filePath":"user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),r={name:"user-guide/settings/hotkeys-page.md"};function i(n,e,l,c,d,u){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="hotkeys-settings-page" tabindex="-1">Hotkeys (Settings Page) <a class="header-anchor" href="#hotkeys-settings-page" aria-label="Permalink to &quot;Hotkeys (Settings Page)&quot;">​</a></h1><p>Three tabs: <strong>Global</strong>, <strong>Plugin Actions</strong>, and <strong>Process Blacklist</strong>. See the <a href="./../hotkeys.html">Hotkeys</a> page for what each shortcut actually does — this page documents the settings UI itself.</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><p><strong>Global Hotkeys</strong> group:</p><ul><li><strong>Show/Hide Quick Search</strong> — recorder control; accepts either a bare modifier (double-tap mode, default <code>Ctrl</code>) or a full combo. Next to it, <strong>Still respond while a fullscreen app is focused</strong> — checkbox, off by default — opts this hotkey (and Quick Switch, and inline-search activation) out of the automatic fullscreen exemption described under <a href="#process-blacklist">Process Blacklist</a> below.</li><li><strong>Quick Switch</strong> — default <code>Ctrl+G</code>.</li></ul><p><strong>Function Keys</strong> group:</p><ul><li>Next Item (<code>Ctrl+N</code>), Previous Item (<code>Ctrl+P</code>), Jump-to-Result modifier (default <code>Ctrl</code>, paired with digits 1–9), Open Actions Menu (<code>Ctrl+O</code>), Complete from Selection (<code>Ctrl+Tab</code>), QuickLook (<code>Alt+P</code>), Previous/Next Keyword History (<code>Alt+Up</code> / <code>Alt+Down</code>), Delete Keyword History Entry (<code>Ctrl+Delete</code>), Open Full Window (default <code>Ctrl+F</code> — opens the full window directly, carrying over the current query; same effect as left-clicking the Quick Window&#39;s own logo and choosing Show Main Window, without that extra click).</li><li>Every recorder here accepts any key or combo you press — including keys like a bare <code>Tab</code> — and that binding takes priority over any hardcoded default meaning that key might otherwise have.</li></ul><p><strong>Quick Navigation</strong> group:</p><ul><li><strong>Double left-click in empty space</strong> — checkbox, default on.</li><li><strong>Middle-click in empty space</strong> — checkbox, default on.</li></ul><h2 id="plugin-actions" tabindex="-1">Plugin Actions <a class="header-anchor" href="#plugin-actions" aria-label="Permalink to &quot;Plugin Actions&quot;">​</a></h2><p>One entry per action a plugin has registered (e.g. copy path, run as admin), grouped by plugin name, each with its own hotkey recorder. Falls back to the plugin&#39;s own suggested default until you change it.</p><h2 id="process-blacklist" tabindex="-1">Process Blacklist <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;Process Blacklist {#process-blacklist}&quot;">​</a></h2><p>Add executable names (e.g. <code>game.exe</code>) whose foreground focus should suppress Lertaro&#39;s global hotkeys, keystroke interception, and the quick navigation double-click/middle-click mouse triggers entirely. Case-insensitive, <code>.exe</code> suffix optional. Supports the same add-one / bulk-edit pattern as the exclusion rules under <strong>Index</strong>: a single-entry textbox plus <strong>Add Process</strong>, a list of existing entries, and a bulk textbox with <strong>Generate Text</strong> / <strong>Apply Text</strong>.</p><p>This is the fix for hotkey conflicts with fullscreen games or other apps that grab raw keyboard input — see <a href="./../troubleshooting.html#the-global-hotkey-doesn-t-respond">Troubleshooting</a>. Any foreground app that&#39;s genuinely full-screen gets the same treatment automatically, with no entry needed here — unless <strong>Still respond while a fullscreen app is focused</strong> (under <strong>Global</strong>, next to Show/Hide Quick Search) is turned on, which opts back out of that exemption entirely. Either way, an active file dialog is always exempt, so quick navigation still works there.</p>',14)])])}const p=t(r,[["render",i]]);export{h as __pageData,p as default};
